INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('441bd5b4-0c81-45bc-a09d-7f629ee1dd3f','org-c20b3a3c-1392-4cf7-9d5d-7d87a51ade89','Sahale Outdoors Nature Camp','other','https://sahaleoutdoors.org/','hello@sahaleoutdoors.org',NULL,'3408 70th Avenue East','Fife','WA','98424',47.2259888,-122.3370591,'Sahale Outdoors runs nature day camps for kids who want to spend their summer outside. Campers learn wilderness skills, identify plants and animals, build forts, cook over a fire, and play group games in the woods. Counselors are trained naturalists who keep groups small and the pace flexible. Campers should come prepared to get muddy and tired in the best possible way. Sessions run from the org base in Fife and at field locations across the south Puget Sound area.','manual','active',0,NULL,NULL,NULL,NULL,50,'2026-05-03T21:46:08.512486+00:00','2026-05-03T21:46:08.512486+00:00');
