INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('49f1776f-c153-4745-8dde-745a052089ae','org-19177202-8ad3-4738-98ad-b94ef6f85250','Summer Camp - Nature Arts & Crafts Week 1 - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy_of_wilderness-week-tacoma/summer-camp-nature-arts-crafts-week-1-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 connecting outdoor skills with arts and crafts. Wednesday and Thursday are field trip days with an easy hike in the Mt. Rainier area focused on nature photography and watercolor painting. Activities may include climbing, rope skills, navigation, wilderness first aid, drawing, mural creation, 3D topographic maps, ropes-based crafts, paper mache, tie-dye, and pyrography. Friday meets at Point Defiance Park. C','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:31:19.706Z','2026-05-08T13:31:19.706Z');
