INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('777db240-884a-404c-aed6-87e4f132caa1','org-f3baa3b8-6468-4e3c-9869-868b2e4f6d7b','Summer Camp - Teen Adventures: Rock Climbing - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy2_of_summer-camp-teen-adventures-intro-backpacking-tacoma/summer-camp-teen-adventures-rock-climbing-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Four-day teen rock climbing adventure for ages 13-17, all experience levels welcome. Tuesday is at the Tacoma Program Center for climbing basics including top-roping, belaying, rappelling, knots, and anchors. Wednesday through Friday is outdoor climbing at Exit 38 and Exit 32 with two nights of camping nearby. Skills covered may include lead belaying, mock-leading, leading on bolts, anchor building, and rescue skills. Participants may hike up to 1 mile with 30-pound packs. Led by Sarah Holt.','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:31:22.190Z','2026-05-08T13:31:22.190Z');
