INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('32b80d5f-4f29-46a5-9221-b991d2e01dbb','org-0b287a88-9115-426e-8683-5a81268bf89a','Summer Camp - Teen Adventures: Backpacking - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/summer-camp-teen-adventures-intro-backpacking-tacoma/summer-camp-teen-adventures-backpacking-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Four-day teen backpacking adventure for ages 13-17, new and experienced backpackers welcome. Tuesday is at the Tacoma Program Center learning backcountry skills including first aid, navigation, the 10 essentials, Leave No Trace principles, and using backpacking gear. Wednesday through Friday is a multi-day backpacking trip in the wilderness covering 5-7 miles per day with 1,000-2,000 feet of elevation gain, carrying packs that weigh 30-35 pounds. Led by Sarah Holt.','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:31:24.072Z','2026-05-08T13:31:24.072Z');
