INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('d2750682-0666-4d1c-a0dd-0449d9480c36','org-628c6b32-7580-49f9-a4de-af012df047f7','Summer Camp - Rock & Ropes 1 - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/summer-camp-rock-ropes-1-tacoma/summer-camp-rock-ropes-1-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on introduction to rock climbing. Campers learn to belay, tie climbing knots, rappel, prusik, and try basic anchor work. Each group gets one outdoor climbing field trip during the week to Exit 38 near North Bend. Friday meets at Point Defiance Park for a hike, picnic, and beach time. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:32:27.152Z','2026-05-08T13:32:27.152Z');
