INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('71a52a78-2ed9-4f8f-ac65-1864ebd22ecb','org-7e265a49-84c1-44d9-ad54-19c72dc1e8e9','Summer Camp - Climbing Rock Stars - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy2_of_summer-camp-rock-ropes-1-tacoma/summer-camp-climbing-rock-stars-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on advancing climbing skills. In addition to top-roping, belaying, and rappelling, campers practice clipping draws, mock-leading, anchor building, and some may lead sport routes. Each group gets one outdoor climbing field trip to Exit 38 near North Bend. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:32:28.483Z','2026-05-08T13:32:28.483Z');
