INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('5a7ded06-9514-4df0-9fe5-7ee0569e6d5c','org-62c37cc5-f861-4fe0-b567-f77a4a180c7a','Summer Camp - Nature Arts & Crafts Week 1 - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy_of_wilderness-week-tacoma/summer-camp-nature-arts-crafts-week-1-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 connecting outdoor skills with arts and crafts. Wednesday and Thursday are field trip days with an easy hike in the Mt. Rainier area focused on nature photography and watercolor painting. Activities may include climbing, rope skills, navigation, wilderness first aid, drawing, mural creation, 3D topographic maps, ropes-based crafts, paper mache, tie-dye, and pyrography. Friday meets at Point Defiance Park. C','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:32:29.048Z','2026-05-08T13:32:29.048Z');
