INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('ee6344a1-0460-4c66-bca4-3dfa6dbb6a54','org-c707d707-872c-4a10-8fe3-cce257a79db6','Summer Camp - Climbing Rock Stars 2 - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy3_of_summer-camp-rock-ropes-1-tacoma/summer-camp-climbing-rock-stars-2-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on advancing climbing skills. Identical curriculum to Climbing Rock Stars 1, simply the second instance of the theme. Activities include top-roping, belaying, rappelling, clipping draws, mock-leading, anchor building, and possibly leading sport routes for ready students. Each group gets one outdoor climbing field trip to Exit 38 near North Bend. Friday meets at Point Defiance Park. Camp runs 8:30am ','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:32:33.025Z','2026-05-08T13:32:33.025Z');
