INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('f3302847-3f65-4db9-b31a-2699b323cde3','org-a607adbf-370f-4b56-8745-6b33b2ca4eea','Summer Camp - Teen Adventures: Backpacking - Tacoma','other','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/summer-camp-teen-adventures-intro-backpacking-tacoma/summer-camp-teen-adventures-backpacking-tacoma-2026','sarahh@mountaineers.org','','2302 N 30th St','Tacoma','WA','98403',47.2745529,-122.4671945,'Four-day teen backpacking adventure for ages 13-17, new and experienced backpackers welcome. Tuesday is at the Tacoma Program Center learning backcountry skills including first aid, navigation, the 10 essentials, Leave No Trace principles, and using backpacking gear. Wednesday through Friday is a multi-day backpacking trip in the wilderness covering 5-7 miles per day with 1,000-2,000 feet of elevation gain, carrying packs that weigh 30-35 pounds. Led by Sarah Holt.','scraped','active',0,NULL,NULL,NULL,NULL,80,'2026-05-08T13:32:33.629Z','2026-05-08T13:32:33.629Z');
