INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('7e280ec3-0502-447c-bc99-d58ed49507d2','org-a051a9c3-1ce5-44fd-a6ae-a188847dce5d','Nike Girls Soccer Camp at Northen Illinois University - Collegiate Experience -  (July 9–11, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-at-niu-collegiate-experience#session-82307-1217502','','','1425 W Lincoln Hwy','Dekalb','IL','60115',41.936642,-88.780997,'Take your game to the next level this summer at the Nike Girls Soccer Camp at Northern Illinois University in DeKalb, Illinois. Led by NIU Women’s Soccer Head Coach Michael O’Neill, a Top 10 Nike Soccer Camp Director, this residential camp delivers a true collegiate training experience both on and off the field. Hosted on a Division I campus with state-of-the-art facilities, campers train in an environment that mirrors the intensity, structure, and professionalism of college soccer. Each session','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T15:01:20.615Z','2026-05-09T15:01:20.615Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('a051a9c3-1ce5-44fd-a6ae-a188847dce5d','7e280ec3-0502-447c-bc99-d58ed49507d2','nike-girls-soccer-camp-at-northen-illinois-university-collegiate-experience-july','Nike Girls Soccer Camp at Northen Illinois University - Collegiate Experience -  (July 9–11, 2026)','camp','soccer','Take your game to the next level this summer at the Nike Girls Soccer Camp at Northern Illinois University in DeKalb, Illinois. Led by NIU Women’s Soccer Head Coach Michael O’Neill, a Top 10 Nike Soccer Camp Director, this residential camp delivers a true collegiate training experience both on and off the field. Hosted on a Division I campus with state-of-the-art facilities, campers train in an environment that mirrors the intensity, structure, and professionalism of college soccer. Each session is designed to help players elevate their technical and tactical skills while building confidence and understanding of the next level. Beyond training, this camp offers a complete residential experience. Campers live on campus and take part in team-building activities like bowling, karaoke, and group events that foster connection, confidence, and lasting friendships. Designed for players ages 10–18, this camp combines elite-level coaching, competitive training, and a fun, supportive atmosphere. It is an unforgettable opportunity for players to improve their game, experience college life, and be part of a positive and inspiring soccer community. Hear from Head Coach and Camp Director Michael O''Neil: “Our residential camp blends elite training with unforgettable fun, giving players a true college-level experience while helping them grow in confidence, connection, and love for the game.”',10,18,'all','2026-07-09','2026-07-11','$489','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-at-niu-collegiate-experience#session-82307-1217502',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T15:01:20.615Z','support@parentcoachdesk.com','2026-05-09 15:11:25','Bulk approve ussportscamps harvester run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T15:01:21.089Z',200,NULL,NULL,'medium','a051a9c3-1ce5-44fd-a6ae-a188847dce5d','nike-girls-soccer-camp-at-northen-illinois-university-collegiate-experience-july','2026-05-09T15:01:20.615Z','2026-05-09T15:01:20.615Z');

