INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('866851b6-4d6e-4337-9c20-c952960d5c76','07dcf945-fa9c-4ea1-be4d-cbe2f9a16ecb','nike-soccer-camp-at-usc-upstate-june-8-12-2026','Nike Soccer Camp at USC Upstate -  (June 8–12, 2026)','camp','soccer','Train in the heart of the Upstate South Carolina soccer community at the Nike Soccer Camp at USC Upstate, located in Spartanburg, South Carolina. This Nike day camp is led by the USC Upstate Men’s Soccer coaching staff, providing players with direct access to collegiate-level instruction in a structured, development-focused environment. Open to players ages 6–14, the camp delivers age-appropriate training that emphasizes technical development, tactical understanding, finishing, and game awareness. Players will be grouped by age and ability in an attempt to develop campers'' ball master/manipulation, and small-sided game-like scenarios all over the field. Sessions are designed to challenge players at every stage while introducing them to the training habits, pace, and skills from collegiate coaches and players.',6,14,'all','2026-06-08','2026-06-12','$250','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-usc-upstate#session-82363-1217577',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplayb