INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('a2af8034-3760-40af-b63d-9ca2b06f86eb','fee5246d-cbd9-4421-9d20-4978e8443d1a','nike-soccer-camp-in-ashburn-day-camp-i-june-22-26-2026','Nike Soccer Camp in Ashburn - Day Camp I (June 22–26, 2026)','camp','soccer','The Nike Soccer Camp in Ashburn, VA delivers a high-quality day camp experience for players ages 7–15 at Moorefield Station Community Park. Located in the heart of Loudoun County, this camp combines elite technical training with a strong emphasis on confidence, leadership, and mindset. Led by FuturElitez, a Northern Virginia–based youth development organization, the camp is open to all skill levels and provides a structured yet supportive environment for players at every stage of development. Daily sessions focus on ball mastery, first touch, passing and receiving, body positioning, and small-sided games, all delivered through the proven Nike Soccer Camp training methodology. What sets this camp apart is FuturElitez''s commitment to leadership development through their specialized coaching and mentoring the youth whilst enhancing the players'' technical skills and dominance.',7,15,'all','2026-06-22','2026-06-26','$350','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-ashburn-northern-virginia-futurelitez#session