INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('47678196-256c-4fbd-89ca-af07a2e95620','org-49703208-01ea-49c1-ac72-bff28f627fc8','Nike Soccer Camp at Metropolitan State University of Denver -  (June 8–12, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-metropolitan-state-denver#session-79682-1213448','','','1600 W Colfax Ave','Denver','CO','80204',39.7403632,-105.0072313,'Get ready for an unforgettable soccer experience at the Nike Soccer Camp at Metropolitan State University of Denver, where boys and girls ages 6–14 can train with two of the top collegiate coaching staffs in the region. Hosted on the beautiful NCAA Division II MSU Denver campus, this camp offers a unique opportunity for young athletes to learn directly from Men’s Head Coach Nick Kirchhof and Women’s Head Coach Katie Hooker, along with their outstanding Roadrunners coaching staff and players. Eve','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T15:09:16.689Z','2026-05-09T15:09:16.689Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('49703208-01ea-49c1-ac72-bff28f627fc8','47678196-256c-4fbd-89ca-af07a2e95620','nike-soccer-camp-at-metropolitan-state-university-of-denver-june-8-12-2026','Nike Soccer Camp at Metropolitan State University of Denver -  (June 8–12, 2026)','camp','soccer','Get ready for an unforgettable soccer experience at the Nike Soccer Camp at Metropolitan State University of Denver, where boys and girls ages 6–14 can train with two of the top collegiate coaching staffs in the region. Hosted on the beautiful NCAA Division II MSU Denver campus, this camp offers a unique opportunity for young athletes to learn directly from Men’s Head Coach Nick Kirchhof and Women’s Head Coach Katie Hooker, along with their outstanding Roadrunners coaching staff and players. Every player will be grouped based on age and ability; some groups may be single-gender, while others may be mixed. The ability to move an athlete within the week will be evaluated to ensure all campers are in a comfortable environment to learn and grow. This format provides an authentic collegiate training experience powered by two successful NCAA programs, giving campers the perfect environment to grow their skills and confidence. Each day features a dynamic mix of technical development, small‑sided games, position‑specific coaching, competitive play, and soccer IQ training. Whether athletes are building foundational skills or refining the details needed to advance to the next level, they’ll be challenged, supported, and inspired by coaches who know how to elevate young talent. With elite instruction, a fun and competitive atmosphere, and the stunning facilities of MSU Denver, this camp delivers one of Colorado’s premier youth soccer experiences. Hear from Head Coach and Camp Director Katie Hooker: "MSU Coed Day Camp is designed for soccer players of all levels to have fun while improving their game in a positive, engaging environment. Players are grouped and adjusted throughout camp based on age and ability to ensure the right balance of challenge, support, and development." Join us this summer and train like a Roadrunner as you take your game to the next level!',6,14,'all','2026-06-08','2026-06-12','$355','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-metropolitan-state-denver#session-79682-1213448',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T15:09:16.689Z','support@parentcoachdesk.com','2026-05-09 15:11:25','Bulk approve ussportscamps harvester run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T15:09:18.453Z',200,NULL,NULL,'medium','49703208-01ea-49c1-ac72-bff28f627fc8','nike-soccer-camp-at-metropolitan-state-university-of-denver-june-8-12-2026','2026-05-09T15:09:16.689Z','2026-05-09T15:09:16.689Z');

