INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('862c9fd5-36ef-488a-83b1-0d83491f4af7','org-147d1e5d-a0e0-40db-ab46-0504f0c7f5ca','Nike Baseball Camp at Boise State University - Day Camp (June 15–18, 2026)','other','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-boise-state-university#session-83158-1218661','','','5600 N Glenwood St','Boise','ID','83706',43.6388515,-116.2747114,'Nike Baseball Camps is excited to return to Boise State University in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of passionate coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 10-17. Overnight Camp Our overnight camp at Boise State offers an immersive, on-campus experience where campers reside in the beautiful BSU dormit','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T15:16:55.973Z','2026-05-09T15:16:55.973Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('147d1e5d-a0e0-40db-ab46-0504f0c7f5ca','862c9fd5-36ef-488a-83b1-0d83491f4af7','nike-baseball-camp-at-boise-state-university-day-camp-june-15-18-2026','Nike Baseball Camp at Boise State University - Day Camp (June 15–18, 2026)','camp','baseball','Nike Baseball Camps is excited to return to Boise State University in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of passionate coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 10-17. Overnight Camp Our overnight camp at Boise State offers an immersive, on-campus experience where campers reside in the beautiful BSU dormitories (just steps from the Boise River) in adjacent rooms to the camp staff while training during the daytime hours. The tuition includes housing, meals, fun evening activities, as well as college recruiting seminars on Tuesday evening (parents are encouraged to attend the seminars!). Day Camp (9:00am – 4:00pm) Nike Baseball Camps also offers a summer day camp program for local athletes. This program runs 9:00am-4:00pm (schedule varies by day) and includes daytime training only. Campers can bring their own lunch or purchase it on campus. Nike Sports Camp Experience At Boise State University, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Golf, Soccer, Softball, Swim, Tennis, and Track &amp; Field) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Baseball Complex/Transportation Information Train like the pros in 2026! The Nike Baseball Camp at BSU will now be conducting all baseball training at Memorial Stadium in Garden City—the official home of the Boise Hawks. Campers and staff will be transported by bus between Boise State and the stadium each day. The Nike Baseball Camp at Boise State University is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by Boise State University.',10,17,'all','2026-06-15','2026-06-18','$529','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-boise-state-university#session-83158-1218661',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T15:16:55.973Z','support@parentcoachdesk.com','2026-05-09 18:36:46','Bulk approve ussportscamps run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T15:16:56.740Z',200,NULL,NULL,'medium','147d1e5d-a0e0-40db-ab46-0504f0c7f5ca','nike-baseball-camp-at-boise-state-university-day-camp-june-15-18-2026','2026-05-09T15:16:55.973Z','2026-05-09T15:16:55.973Z');

