INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('82f448a3-fdbc-45d9-9ec1-896eba52cb4a','org-09d28a6f-4748-4ad6-a116-ad3a465f52c8','Nike Tennis Camp at Lipscomb University Racquet Club - Tiny Bison & Jr. Bison (May 26–29, 2026)','other','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-lipscomb-racquet-club#session-80323-1214709','','','Lipscomb University Racquet Club One University Park Drive','Nashville','TN','37204',NULL,NULL,'Join us at the highly rated Nike Tennis Camp in Nashville, hosted at the Lipscomb University Racquet Club. A top choice for summer tennis in Tennessee, our camp offers live drills, tactical tennis training, match play, and a comprehensive conditioning program. This camp is designed for beginner and intermediate tennis players ages 4-17. The Tiny Bison program is tailored for beginner players ages 4-7, while the Junior Bison program focuses on intermediate players ages 8-17. Campers are evaluated','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T15:34:49.014Z','2026-05-09T15:34:49.014Z');
