INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('981789ad-7adc-431d-b3dc-785e336ba1c2','894b93f1-9599-40c4-b9a3-ecfacf3ffe6d','nike-adult-tennis-camp-at-weston-racquet-club-doubles-tennis-matchplay-master-co','Nike Adult Tennis Camp at Weston Racquet Club - Doubles Tennis & Matchplay Master Course (May 23–24, 2026)','camp','tennis','Doubles Tactics &amp; Matchplay Master Course Join us for an action packed tennis clinic weekend focused entirely on doubles strategy and performance. Whether you''re preparing for league play, want to sharpen your court awareness, or just love the dynamic of doubles, this session is for you. Aimed at players between 2.5-4.0 USTA rating. This program is perfect for players who want to improve their doubles instincts, shot selection, and teamwork—all in a fun, supportive, and challenging environment. Spaces are limited to 16 players, so early sign-up is strongly encouraged! Highlights: Positional drills to master net play, court coverage &amp; communicationTactical instruction for serving strategies, poaching, and returning as a teamLive match play rotations with feedbackServe &amp; volley practice, lob coverage, and middle control drillsGuidance from experienced coach Adam Maddock, bringing a wealth of coaching and competitive insight Adult Beginner Tennis Crash Course Looking to finally learn tennis or get back into the game with confidence? Our Adult Beginner Crash Course is the perfect place to start. Over 6 hours of professional instruction across two sessions, you’ll get hands-on experience and structured guidance in a welcoming, social environment—no pressure, just progress! Whether your goal is to join weekly clinics, play social matches, or just pick up a fun new skill, this crash course is your perfect launchpad. What You''ll Learn: Proper grip and stroke fundamentals (forehands, backhands, serves &amp; volleys)Court positioning and movement basicsScoring, rules, and match etiquetteHow to rally and play real pointsFun games and drills to build your confidence and consistency What''s Included: Racquets available to borrow (no need to buy one yet!)Drinks and light snacks providedSmall group sizes for individual attentionLed by certified coaches with years of experience',18,22,'all','2026-05-23','2026-05-24','$299','day',0,0,'open','https://www.ussportscamps.com/tennis/nike/nike-adult-tennis-camp-at-weston-racquet-club#session-83763-1219477',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T15:36:56.830Z','support@parentcoachdesk.com','2026-05-09 18:36:46','Bulk approve ussportscamps run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T15:36:57.194Z',200,NULL,NULL,'medium','981789ad-7adc-431d-b3dc-785e336ba1c2','nike-adult-tennis-camp-at-weston-racquet-club-doubles-tennis-matchplay-master-co','2026-05-09T15:36:56.830Z','2026-05-09T15:36:56.830Z');

