INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('a44ed2a4-00bb-4e32-8534-872468a95f34','ecb2bf56-5eca-4244-ac6c-d1d10a1ccfba','nike-baseball-camp-at-southern-new-hampshire-university-july-20-23-2026','Nike Baseball Camp at Southern New Hampshire University -  (July 20–23, 2026)','camp','baseball','Get ready for a great baseball experience at the Nike Baseball Camp at Southern New Hampshire University in Manchester, NH! This camp offers young athletes the perfect opportunity to sharpen their skills, learn from top coaches, and have a blast on the field. Campers will develop their hitting, fielding, and base-running techniques through high-energy drills and fun, competitive play—and they’ll leave with more confidence and excitement for the game than ever before. We’re thrilled to welcome everyone back for two great weeks of camp in 2026! Former SNHU Head Coach Scott Loiseau will lead camp activities, supported by the talented Penmen coaching staff and players. Designed for athletes ages 6–12, the camp groups players by age and ability to ensure personalized instruction and growth for every level. The focus is on building strong fundamentals, teamwork, and a deeper love for the game. Spots fill up fast—don’t miss your chance to join the fun!',6,12,'all','2026-07-20','2026-07-23','$399','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-southern-new-hampshire-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:32:50.267Z','support@parentcoachdesk.com','2026-05-09 18:36:46','Bulk approve ussportscamps run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:32:52.528Z',200,NULL,NULL,'medium','a44ed2a4-00bb-4e32-8534-872468a95f34','nike-baseball-camp-at-southern-new-hampshire-university-july-20-23-2026','2026-05-09T18:32:50.267Z','2026-05-09T18:32:50.267Z');

