INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('39918981-7e7c-4f5d-ac0c-55724fbf6bfb','org-01554fd4-ecdb-4d7c-9d70-581ab5f0d4fc','Nike Baseball Camp at Union University -  (July 13–16, 2026)','other','https://www.ussportscamps.com/baseball/nike/baseball-camp-union-university','','','Joyce Barefoot Dr','Jackson','TN','38305',35.6757051,-88.8583989,'Join us this summer for the Nike Baseball Camp at Union University in Jackson, Tennessee! This new camp offers a fun and engaging opportunity for young athletes to develop their baseball skills in a positive and instruction-focused environment. The camp will run July 13–16 from 9:00am–3:00pm and is open to boys ages 7–14. Designed for beginner and intermediate players, this camp welcomes athletes of all abilities who are eager to learn, improve, and enjoy the game. Throughout the week, campers w','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T18:33:13.389Z','2026-05-09T18:33:13.389Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('01554fd4-ecdb-4d7c-9d70-581ab5f0d4fc','39918981-7e7c-4f5d-ac0c-55724fbf6bfb','nike-baseball-camp-at-union-university-july-13-16-2026','Nike Baseball Camp at Union University -  (July 13–16, 2026)','camp','baseball','Join us this summer for the Nike Baseball Camp at Union University in Jackson, Tennessee! This new camp offers a fun and engaging opportunity for young athletes to develop their baseball skills in a positive and instruction-focused environment. The camp will run July 13–16 from 9:00am–3:00pm and is open to boys ages 7–14. Designed for beginner and intermediate players, this camp welcomes athletes of all abilities who are eager to learn, improve, and enjoy the game. Throughout the week, campers will train with experienced coaches and players who are passionate about teaching the fundamentals of baseball. Daily instruction will include skill development in hitting, pitching, catching, infield and outfield play, baserunning, and defensive fundamentals. Campers will work through drills and position-specific instruction that focuses on proper mechanics, improving baseball IQ, and building confidence on the field. In addition to skill development, campers will take part in games, competitions, and fun challenge-based activities designed to reinforce teamwork, toughness, and a competitive spirit. Coaches will emphasize situational awareness, smart decision-making, and competing with the right attitude while creating an energetic and supportive atmosphere. The Nike Baseball Camp at Union University is built to help players grow both as athletes and teammates. Whether your child is just beginning their baseball journey or looking to sharpen their skills, this camp provides a fun and encouraging environment where players can improve, build confidence, and develop a passion for the game',7,14,'all','2026-07-13','2026-07-16','$359','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/baseball-camp-union-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:33:13.389Z','support@parentcoachdesk.com','2026-05-09 18:36:46','Bulk approve ussportscamps run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:33:14.111Z',200,NULL,NULL,'medium','01554fd4-ecdb-4d7c-9d70-581ab5f0d4fc','nike-baseball-camp-at-union-university-july-13-16-2026','2026-05-09T18:33:13.389Z','2026-05-09T18:33:13.389Z');

