INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('c26873f8-1534-4d42-92aa-de74989cc4bb','org-3e61dca6-6392-49be-ac1e-ef80aed70200','Nike Baseball Camp at Saint Joseph’s University -  (June 29–July 2, 2026)','other','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-st-joseph-university','','','394 N Latches Ln','Merion Station','PA','19066',NULL,NULL,'Join us this summer at John W. Smithson Field on the campus of Saint Joseph’s University in Philadelphia, PA, for an exciting week of baseball development at the Nike Baseball Camp directed by SJU Head Coach Fritz Hamburg. This camp provides young athletes with high-level instruction, competitive drills, and a fun training environment designed to elevate their game. Coach Hamburg and his staff will offer two tailored divisions to ensure players train at the right pace and skill level: Beginner D','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T18:33:23.895Z','2026-05-09T18:33:23.895Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('3e61dca6-6392-49be-ac1e-ef80aed70200','c26873f8-1534-4d42-92aa-de74989cc4bb','nike-baseball-camp-at-saint-joseph-s-university-june-29-july-2-2026','Nike Baseball Camp at Saint Joseph’s University -  (June 29–July 2, 2026)','camp','baseball','Join us this summer at John W. Smithson Field on the campus of Saint Joseph’s University in Philadelphia, PA, for an exciting week of baseball development at the Nike Baseball Camp directed by SJU Head Coach Fritz Hamburg. This camp provides young athletes with high-level instruction, competitive drills, and a fun training environment designed to elevate their game. Coach Hamburg and his staff will offer two tailored divisions to ensure players train at the right pace and skill level: Beginner Division: Boys ages 7–11 who are newer to the game and looking to build strong fundamentals.Intermediate Division: Boys ages 12–14 with prior playing experience who want to sharpen their skills and improve their baseball IQ.Please note: This camp is not intended for high school players. Athletes can choose between full-day and half-day camp options, making it easy to find the perfect fit for your schedule and training needs. Each day will include position-specific instruction, hitting and fielding work, team challenges, and positive competition—all led by experienced collegiate coaches committed to helping young players grow. Whether your athlete is taking their first steps in the sport or striving to reach the next level, the Nike Baseball Camp at Saint Joseph’s University is the perfect place to train, compete, and have fun this summer.',7,11,'all','2026-06-29','2026-07-02','$259-$379','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-st-joseph-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:33:23.895Z','support@parentcoachdesk.com','2026-05-09 18:36:46','Bulk approve ussportscamps run',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:33:24.834Z',200,NULL,NULL,'medium','3e61dca6-6392-49be-ac1e-ef80aed70200','nike-baseball-camp-at-saint-joseph-s-university-june-29-july-2-2026','2026-05-09T18:33:23.895Z','2026-05-09T18:33:23.895Z');

