INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('78c82250-5c6e-4297-b9eb-4d604572133a','f543195c-45fc-430b-a8f0-feec4faf7318','nike-baseball-camp-at-elmira-college-july-6-9-2026-r69i','Nike Baseball Camp at Elmira College -  (July 6–9, 2026)','camp','baseball','The Nike Baseball Camp at Elmira College is thrilled to be back for the 2026 camp season! Head Coach of the Eagles, Anthony Goncalves, is excited to welcome familiar and new ballplayers who are looking to improve their skills. This will be a great opportunity to learn from collegiate coaches with a wide range of knowledge and expertise about the game of baseball. Coach Goncalves will be entering his fifth year at the helm of the Eagles, having first joined the program as an assistant in 2021 before becoming its second-ever head coach. Under his guidance, the team has broken several in-season offensive records, such as slugging percentage (.406), on-base percentage (.404), home runs (23), and hit-by-pitches (75). Defensively, Elmira set program bests for fewest hits (287) and walks (182) allowed, along with a single-game strikeout record of 16 against Alfred! Coach Goncalves and his staff are looking forward to sharing their knowledge and encourage everyone to register!',7,13,'all','2026-07-06','2026-07-09','$309','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-elmira-college',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:41:25.972Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:41:26.343Z',200,NULL,NULL,'medium','78c82250-5c6e-4297-b9eb-4d604572133a','nike-baseball-camp-at-elmira-college-july-6-9-2026-r69i','2026-05-09T18:41:25.972Z','2026-05-09T18:41:25.972Z');

