INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('feb059f5-be69-4a67-a1e6-26702c8747b4','7d21f762-6ada-4a7f-857d-1b9623e09cbf','nike-baseball-camp-at-edgewood-university-aug-10-13-2026-9i81','Nike Baseball Camp at Edgewood University -  (Aug. 10–13, 2026)','camp','baseball','Get ready for another outstanding Nike Baseball Camp at Edgewood University in Verona, Wisconsin! After a fantastic 2025 camp, the coaching staff is energized and ready to make 2026 even better. Athletes of all abilities are encouraged to join us this summer to gain valuable baseball experience and create lasting memories. Quality facilities, knowledgeable coaches, and a positive, growth-focused environment continue to define this camp. All baseball fundamentals will be covered, including throwing, running, fielding, batting, bunting, baserunning, and pitching. Along with instruction and drill work, campers will enjoy fun, modified drills and games designed to enhance skill development. Pitchers and catchers won’t want to miss the additional Pitching/Catching Session on Friday the 14th—a great opportunity to refine mechanics and elevate performance both on the mound and behind the plate.',7,13,'all','2026-08-10','2026-08-13','$349','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-edgewood-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:41:27.512Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:41:29.096Z',200,NULL,NULL,'medium','feb059f5-be69-4a67-a1e6-26702c8747b4','nike-baseball-camp-at-edgewood-university-aug-10-13-2026-9i81','2026-05-09T18:41:27.512Z','2026-05-09T18:41:27.512Z');

