ends.',7,13,'all','2026-06-22','2026-06-24','$279','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-evansville-otters',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:41:35.396Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:41:36.919Z',200,NULL,NULL,'medium','d7f10912-c2c8-454f-90d0-dbd942e00ea7','nike-baseball-camp-at-bosse-field-directed-by-evansville-otters-june-22-24-2026-ltsx','2026-05-09T18:41:35.396Z','2026-05-09T18:41:35.396Z');

