INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('3eac55e9-c2cf-4cfa-b3ad-1bbb081584f6','f8cb827a-9748-4571-bf6e-80413a6cea00','nike-baseball-camp-at-uwm-field-directed-by-united-states-professional-baseball--tp8w','Nike Baseball Camp at UWM Field, directed by United States Professional Baseball League -  (Aug. 3–5, 2026)','camp','baseball','Join us in the summer of 2026 for an exciting Nike Baseball Camp at UWM Field in Utica, MI, the home field of the United States Professional Baseball League (USPBL)! The camp will be led by Justin Karn,Manager of the Westside Woolly Mammoths and member of the USPBL coaching staff for the past four years. Karn brings extensive collegiate coaching experience from programs such as Madonna University, Oakland University, and St. Thomas Aquinas, where he helped guide teams to championships and national tournament appearances. His proven track record of developing talent at both the collegiate and professional levels makes this a can''t-miss opportunity for aspiring ballplayers. Campers 7-12 years old will have an awesome time making new friends, memories, and gaining baseball skills that will help them become better players on the field. Don''t miss this opportunity to be instructed by players and coaches from the Birmingham Bloomfield Beavers, Eastside Diamond Hoppers, Utica Unicorns, and the Westside Woolly Mammoths. Sign up today!',7,12,'all','2026-08-03','2026-08-05','$325','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-united-states-professional-baseball-league',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:42:19.966Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:42:21.427Z',200,NULL,NULL,'medium','3eac55e9-c2cf-4cfa-b3ad-1bbb081584f6','nike-baseball-camp-at-uwm-field-directed-by-united-states-professional-baseball--tp8w','2026-05-09T18:42:19.966Z','2026-05-09T18:42:19.966Z');

