INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('a1c0a536-4644-45d8-ad0c-e29e3f8e5b78','f68a8c8f-c4b7-43f9-b282-faafe9a4f22a','nike-baseball-camp-at-university-of-la-verne-june-22-25-2026-j0mp','Nike Baseball Camp at University of La Verne -  (June 22–25, 2026)','camp','baseball','Get ready for the Nike Baseball Camps at the University of La Verne in Southern California! All baseball players that attend will learn valuable skills that they can transfer into their game to help them become better baseball players. Instruction will cover all aspects of baseball including fielding, hitting, baserunning, and team play. Summer is the perfect time to continue perfecting your love of the game and Director Scott Winterburn is confident he can help your camper reach their goals. Scott Winterburn, who took over the University of La Verne baseball program in 2001 after coaching at Azusa Pacific University, has built a powerhouse program over his tenure. Under his leadership, the Leopards have captured eight SCIAC titles (2004, 2005, 2008, 2012, 2018, 2023, 2024, and 2025), earned multiple Top 20 national rankings, made several NCAA tournament appearances, two super regional appearances (2023 and 2024), and two SCIAC Postseason Tournament Championships (2015 and 2025). Winterburn has also developed numerous standout players, coaching six SCIAC Players or Pitchers of the Year—all of whom earned All-America honors—and producing 43 All-West Region selections and 9 total All-Americans.',8,13,'all','2026-06-22','2026-06-25','$429','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-university-of-la-verne-1',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:42:39.111Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:42:40.373Z',200,NULL,NULL,'medium','a1c0a536-4644-45d8-ad0c-e29e3f8e5b78','nike-baseball-camp-at-university-of-la-verne-june-22-25-2026-j0mp','2026-05-09T18:42:39.111Z','2026-05-09T18:42:39.111Z');

