INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('45a1f313-153d-4d03-b69a-2828a87a93fa','1f2ec777-e9e7-4cb2-983a-4f80543f4fa2','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-6-10-2026-8uh0','Nike Baseball Camp at On-Deck in Prince George’s County -  (July 6–10, 2026)','camp','baseball','The Nike Baseball Camp at On-Deck in Prince George’s County offers a high-level training experience in an intimate, athlete-focused environment. Directed by Andre Hockaday and the professional coaching staff at On-Deck, this camp is designed for players who want focused instruction, personalized feedback, and serious skill development—without losing the fun of the game. This summer, the camp will run four weekly sessions throughout the month of July, with camp held Monday through Friday from 9:00am–3:00pm. Each week features four days of skill development inside the state-of-the-art On-Deck indoor facility, followed by a final day of live scrimmages and gameplay on the turf baseball field at Prince George’s Community College. The On-Deck facility is a 7,000-square-foot, air-conditioned training space equipped with a large indoor turf field, five batting cages, and modern baseball training technology. With just 50 campers per week, athletes receive extensive one-on-one instruction and small-group coaching from experienced professional baseball coaches and trainers. Campers can expect a well-rounded experience that blends advanced skill development, competitive gameplay, and a positive, high-energy atmosphere—all built to help players grow their confidence, sharpen their skills, and enjoy every day at camp.',6,12,'all','2026-07-06','2026-07-10','$399','day',0,0,'open','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-on-deck-prince-georges-county',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T18:43:23.723Z','support@parentcoachdesk.com','2026-05-09 18:51:04','Bulk approve ussportscamps full sweep',NULL,0,0,0,NULL,NULL,'live','2026-05-09T18:43:25.030Z',200,NULL,NULL,'medium','45a1f313-153d-4d03-b69a-2828a87a93fa','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-6-10-2026-8uh0','2026-05-09T18:43:23.723Z','2026-05-09T18:43:23.723Z');

