INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('53fbafc8-6cf2-4e24-b86c-9c8314f9df1c','org-6ce5b2c9-71ca-4850-b642-588aef3a988e','Nike Soccer Camp at Brookfield Sports Complex -  (June 15–19, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-brookfield-sports-complex-wi','','','W212N4933 Weyer Rd','Menomonee Falls','WI','53051',43.10705,-88.1753442,'Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp at Brookfield Sports Complex with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level!','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:19:14.932Z','2026-05-09T20:19:14.932Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('6ce5b2c9-71ca-4850-b642-588aef3a988e','53fbafc8-6cf2-4e24-b86c-9c8314f9df1c','nike-soccer-camp-at-brookfield-sports-complex-june-15-19-2026-cz2k','Nike Soccer Camp at Brookfield Sports Complex -  (June 15–19, 2026)','camp','soccer','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp at Brookfield Sports Complex with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: “We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.”',6,16,'all','2026-06-15','2026-06-19','$435','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-brookfield-sports-complex-wi',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:19:14.932Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:19:16.825Z',200,NULL,NULL,'medium','6ce5b2c9-71ca-4850-b642-588aef3a988e','nike-soccer-camp-at-brookfield-sports-complex-june-15-19-2026-cz2k','2026-05-09T20:19:14.932Z','2026-05-09T20:19:14.932Z');

