INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('8527c6cd-57aa-40cf-aaed-ab5a372922f2','12933e33-40ec-4136-8f51-4c204800f1e0','nike-soccer-camp-at-oregon-state-university-july-5-9-2026-pm6m','Nike Soccer Camp at Oregon State University -  (July 5–9, 2026)','camp','soccer','Join us for the Nike Soccer Camp at Oregon State University in Corvallis, Oregon, an immersive overnight soccer camp that has sold out three consecutive years. Set on the beautiful Oregon State campus, this premier residential camp offers the complete college-style experience, combining elite soccer training with engaging off-the-field and social activities. Designed for boys and girls ages 6–17, this co-ed Nike Soccer Camp is led by passionate, experienced coaches committed to helping players accelerate their development. Campers train daily using a blend of modern and traditional coaching methods, focusing on technical skill development, tactical understanding, and confident decision-making in game-like situations. The overnight format allows athletes to fully experience campus life, build friendships, and participate in structured evening activities that complement their soccer training. This balance of high-level coaching and a truly immersive residential experience creates an environment where players grow both as athletes and as individuals. Whether your goal is to improve technical ability, boost soccer IQ, or experience what it’s like to train in a top-tier college soccer environment, the Nike Soccer Camp at Oregon State University delivers a fun, competitive, and unforgettable summer camp experience.',6,17,'all','2026-07-05','2026-07-09','$449-$919','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-oregon-state-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:19:20.863Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:19:21.127Z',200,NULL,NULL,'medium','8527c6cd-57aa-40cf-aaed-ab5a372922f2','nike-soccer-camp-at-oregon-state-university-july-5-9-2026-pm6m','2026-05-09T20:19:20.863Z','2026-05-09T20:19:20.863Z');

