INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('1fa11b41-5359-4b4f-a508-91fb7f507ec4','26ae2d41-5c74-42d2-ad24-c029dbbb095f','nike-soccer-camp-in-west-seattle-all-skills-i-june-22-26-2026','Nike Soccer Camp in West Seattle - All Skills I (June 22–26, 2026)','camp','soccer','Rich Schreiner was voted a Top-10 Nike Soccer Camp Director in 2025 by players and parents! Join us for an exciting opportunity to elevate your game at the Nike Soccer Camp in West Seattle.. Supervised by the experienced coaching staff and players of Seattle University, this camp offers young soccer enthusiasts the chance to sharpen their skills in a dynamic, inclusive environment. Whether you''re looking to improve technical abilities, tactical understanding, or team coordination, you''ll be guided by passionate coaches in one of Seattle''s most vibrant communities. Don''t miss this chance to train like a pro, learn from the best, and enjoy the beautiful Pacific Northwest surroundings. This camp was held at Georgetown Playfield in 2023 but returned to Delridge Playfield in 2024 and 2025. This summer, we are offering three weeks at Del Ridge and one week at Hiawatha Playfield (July 13-17)',5,12,'all','2026-06-22','2026-06-26','$339-$469','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-seattle-delridge-playfields',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:19:55.300Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:19:57.170Z',200,NULL,NULL,'medium','1fa11b41-5359-4b4f-a508-91fb7f507ec4','nike-soccer-camp-in-west-seattle-all-skills-i-june-22-26-2026','2026-05-09T20:19:55.300Z','2026-05-09T20:19:55.300Z');

