INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('31136bf8-827f-41c7-99a0-3d33fcd2a54a','org-075f816d-01d0-48f5-a945-24427c8d2ef8','San Francisco Soccer Camp - Youth Academy I (June 8–12, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-san-francisco','','','1400-1598 John F Kennedy Dr','San Francisco','CA','94121',NULL,NULL,'San Francisco Soccer Camp powered by Nike Soccer Camps, was voted as a Top-10 Nike Soccer Camp by parents in 2025(Top Camp in 2024)! Join us for an amazing week of camp at San Francisco Soccer Camp. Team up with Camp Director and 2023 Pac-12 Coach of the Year Leonard Griffin for the ultimate soccer training camp! San Francisco Soccer Camp (SFSC) offers so much more than your average soccer camp for players of all ability levels! Camps are led by a College Coaching Staff and additional support fr','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:19:59.775Z','2026-05-09T20:19:59.775Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('075f816d-01d0-48f5-a945-24427c8d2ef8','31136bf8-827f-41c7-99a0-3d33fcd2a54a','san-francisco-soccer-camp-youth-academy-i-june-8-12-2026','San Francisco Soccer Camp - Youth Academy I (June 8–12, 2026)','camp','soccer','San Francisco Soccer Camp powered by Nike Soccer Camps, was voted as a Top-10 Nike Soccer Camp by parents in 2025(Top Camp in 2024)! Join us for an amazing week of camp at San Francisco Soccer Camp. Team up with Camp Director and 2023 Pac-12 Coach of the Year Leonard Griffin for the ultimate soccer training camp! San Francisco Soccer Camp (SFSC) offers so much more than your average soccer camp for players of all ability levels! Camps are led by a College Coaching Staff and additional support from elite college players to bring the camper-to-coach ratio down. A note from Leonard Griffin, Head Coach, CAL Men''s Soccer: "At the heart of our camp is the belief that high character leads to high performance. As a player, I saw firsthand how the most successful teams — both in college and professionally — were built on strong values, discipline, and teamwork. As a college coach, I’ve carried that lesson into every team I’ve led. That’s why, when we brought the Cal Men’s Soccer experience to San Francisco Soccer Camp, we knew character development had to be embedded into our program.But it’s not just about building strong individuals; it’s also about ensuring that the game remains fun. Just like with our college players, we make it a priority that every camper understands the joy of soccer. Too often, we see young athletes losing sight of why they fell in love with the game in the first place. At San Francisco Soccer Camp, we create a space where players can work hard, grow technically, and most importantly — have fun. It’s that balance of passion, skill, character, and joy that makes our camp so unique."',5,9,'all','2026-06-08','2026-06-12','$719','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-san-francisco',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:19:59.775Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:20:01.331Z',200,NULL,NULL,'medium','075f816d-01d0-48f5-a945-24427c8d2ef8','san-francisco-soccer-camp-youth-academy-i-june-8-12-2026','2026-05-09T20:19:59.775Z','2026-05-09T20:19:59.775Z');

