INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('7ef5ea9f-ad60-4394-93b2-42103a907766','org-9481cd0e-56e3-4eb5-9dae-b16f7cefec53','Nike Soccer Camp at Marquette University -  (June 22–26, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-marquette-university','','','1818 W Canal St','Milwaukee','WI','53233',43.0321249,-87.9360964,'Take your game to the next level this summer at the Nike Soccer Camp at Marquette University in Milwaukee, Wisconsin. Open to players of all abilities, this camp offers a unique opportunity to train with Head Coach David Korn, a Top-10 Rated Nike Soccer Camp Director, along with Marquette University coaches and players, at Valley Fields, home of the Marquette Golden Eagles. Our staff is dedicated to helping each athlete grow in skill, confidence, character, and love for the game. Training sessio','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:20:47.330Z','2026-05-09T20:20:47.330Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('9481cd0e-56e3-4eb5-9dae-b16f7cefec53','7ef5ea9f-ad60-4394-93b2-42103a907766','nike-soccer-camp-at-marquette-university-june-22-26-2026','Nike Soccer Camp at Marquette University -  (June 22–26, 2026)','camp','soccer','Take your game to the next level this summer at the Nike Soccer Camp at Marquette University in Milwaukee, Wisconsin. Open to players of all abilities, this camp offers a unique opportunity to train with Head Coach David Korn, a Top-10 Rated Nike Soccer Camp Director, along with Marquette University coaches and players, at Valley Fields, home of the Marquette Golden Eagles. Our staff is dedicated to helping each athlete grow in skill, confidence, character, and love for the game. Training sessions are designed to challenge experienced players while also supporting newer athletes through a strong foundation of ball skills and game understanding. Campers are grouped by age and ability to ensure the right level of development for every player. The curriculum blends technical training and tactical instruction with small-sided games and competitive scenarios that reinforce teamwork, decision-making, and overall game awareness. Beyond skill development, we emphasize character, leadership, and what it means to be a great teammate. This youth soccer camp in Milwaukee provides the perfect balance of high-level coaching and fun, giving players the chance to improve, compete, make friends, and create lasting summer memories. Hear from Men''s Head Coach &amp; Camp Director, David Korn: "Our staff is dedicated to helping each athlete progress to the next level of their game while growing in confidence, character, and love for the sport."',6,14,'all','2026-06-22','2026-06-26','$319-$439','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-marquette-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:20:47.330Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:20:49.184Z',200,NULL,NULL,'medium','9481cd0e-56e3-4eb5-9dae-b16f7cefec53','nike-soccer-camp-at-marquette-university-june-22-26-2026','2026-05-09T20:20:47.330Z','2026-05-09T20:20:47.330Z');

