INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('09fb8c08-c159-4ea6-a3bd-111c7c561a9c','1776fcf8-8992-4258-b76a-488d817a8468','nike-boys-soccer-camp-at-rollins-college-july-18-21-2026','Nike Boys Soccer Camp at Rollins College -  (July 18–21, 2026)','camp','soccer','Join us for the Nike Boys Soccer Camp at Rollins College in Winter Park, Florida, just outside of Orlando, where players train in a true collegiate environment with one of the nation’s top programs. Led by Head Men’s Soccer Coach Keith Buckley and the Rollins College coaching staff, this camp offers athletes the opportunity to experience college‑level training while developing their game at a higher level. Training sessions blend traditional and modern coaching methodologies, focusing on technical refinement, tactical understanding, and intelligent decision‑making in game‑like situations. The curriculum is designed to challenge players and help every camper continue progressing toward the next level of play in a competitive, supportive atmosphere. In addition to elite on‑field training, the camp includes a college recruiting seminar, giving players valuable insight into the recruitment process and what it takes to play soccer at the collegiate level. Athletes leave camp with improved skills, greater soccer IQ, and a clearer understanding of the demands of high‑level soccer. The Nike Boys Soccer Camp at Rollins College delivers a meaningful collegiate training experience that prepares motivated players to grow, compete, and take the next step in their soccer journey.',10,18,'all','2026-07-18','2026-07-21','$599-$699','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-rollins-college',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:20:53.312Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:20:54.848Z',200,NULL,NULL,'medium','09fb8c08-c159-4ea6-a3bd-111c7c561a9c','nike-boys-soccer-camp-at-rollins-college-july-18-21-2026','2026-05-09T20:20:53.312Z','2026-05-09T20:20:53.312Z');

