INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('bba32667-fead-4278-89fc-d48dd9736fdc','3116836e-344a-4b3d-9f7e-a6f1301898ca','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-1-5-2026','Nike Soccer & Swim Camp with HUB Sports at Windgate Ranch -  (June 1–5, 2026)','camp','soccer','Experience the ultimate summer training adventure as HUB Sports and Nike Soccer Camps team up to deliver an energizing mix of outdoor soccer development and refreshing pool time at Windgate Ranch in Scottsdale, AZ. Set on a beautifully maintained event field and featuring a stunning resort‑style swimming pool, this camp offers the perfect combination of high‑level instruction, competitive play, and summer fun. This unique Soccer &amp; Swim program keeps players active, engaged, and cool under the Scottsdale sun. Campers will enjoy a dynamic blend of technical training, small‑sided games, and skill‑building challenges, followed by scheduled swim sessions designed to help athletes beat the heat, recover, and have fun in a safe and supervised environment. With top‑tier coaching, a vibrant outdoor setting, and the added bonus of pool time, this camp delivers an unforgettable summer experience where kids can learn, grow, and stay cool all week long. Don’t miss your chance to train, play, and splash your way into the best week of the summer! Note: Swim instruction is available exclusively during summer camp weeks. Soccer/swim availability is listed on the schedule for each session.',5,14,'all','2026-06-01','2026-06-05','$299','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-swim-camp-hub-sports-windgate-ranch-scottsdale',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:21:24.178Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:21:25.793Z',200,NULL,NULL,'medium','bba32667-fead-4278-89fc-d48dd9736fdc','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-1-5-2026','2026-05-09T20:21:24.178Z','2026-05-09T20:21:24.178Z');

