INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('1a85bae0-6394-402d-b60b-4ad057def20f','17cfc4f9-949b-4ca4-a3c3-90d6ee65cf47','nike-soccer-camp-at-cabrillo-college-june-8-12-2026-xku1','Nike Soccer Camp at Cabrillo College -  (June 8–12, 2026)','camp','soccer','Get ready for an unforgettable summer of soccer at the Nike Soccer Camp at Cabrillo College in Aptos, California, a program so popular that many camp weeks have sold out the past two years! Boys and girls ages 7–14 will train on the beautiful, state‑of‑the‑art fields of Cabrillo College’s stunning coastal campus, creating the perfect backdrop for elite coaching, high‑energy development, and nonstop fun. Led by Cabrillo College Men’s Soccer Head Coach Paolo Carbone, this camp delivers a top‑tier training experience powered by a blend of time‑tested methodologies and modern player‑development techniques. Coach Carbone and his experienced staff create an environment where every athlete, whether brand‑new to the game or pushing toward competitive levels, can confidently elevate skills, improve soccer IQ, and unlock their full potential. Each day features dynamic technical drills, fast‑paced activities, small‑sided games, and competitive gameplay designed to inspire creativity, sharpen decision‑making, and build a true love for the sport. Combined with Cabrillo College’s premium training facilities and an upbeat, supportive camp culture, this program offers one of the most exciting and sought‑after youth soccer experiences in the Santa Cruz and Monterey Bay region. Join us this summer and experience why the Nike Soccer Camp at Cabrillo College continues to sell out every year—train with elite coaches, develop your game, and enjoy an unforgettable week of soccer excellence!',7,14,'all','2026-06-08','2026-06-12','$325-$435','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-cabrillo-college',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:21:32.124Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:21:33.545Z',200,NULL,NULL,'medium','1a85bae0-6394-402d-b60b-4ad057def20f','nike-soccer-camp-at-cabrillo-college-june-8-12-2026-xku1','2026-05-09T20:21:32.124Z','2026-05-09T20:21:32.124Z');

