INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('6aa33de7-17d9-4fcd-bfca-bb1ff2b29cd1','4d134c2c-5312-4739-b2ad-f558e5091821','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-8-12-2026-ttfp','Nike Soccer Camp with JM Soccer Academy in Las Vegas -  (June 8–12, 2026)','camp','soccer','Join us this summer at the Nike Soccer Camp at the beautiful Somerset Academy, Skypointe Campus in Las Vegas, NV! Designed for boys and girls ages 4–14, this premier camp offers both morning and full‑day options for an unforgettable soccer experience. The outdoor morning camp runs from 8:00am–11:00am, perfect for training during the coolest part of the day, while the full‑day option adds exciting indoor futsal training, giving players fast‑paced, exclusive play while beating the heat. Directed by JM Soccer Academy and led by former professional player Jordan Murrell, the camp features modern, age‑appropriate coaching focused on technical skill, confidence, and creativity. A fun 90‑minute program for ages 4–5 introduces the game through movement and foundational skills, while players ages 6–14 enjoy high‑energy training with fast‑paced drills, small‑sided games, and competitive play, plus indoor futsal sessions for full‑day campers. With elite coaching, a premier campus setting, and the proven Nike Soccer Camps experience, this is one of the most exciting soccer camps in Las Vegas. Train. Play. Compete. And take your game to the next level this summer!',4,14,'all','2026-06-08','2026-06-12','$155-$385','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-las-vegas-nv',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:22:50.748Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:22:52.371Z',200,NULL,NULL,'medium','6aa33de7-17d9-4fcd-bfca-bb1ff2b29cd1','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-8-12-2026-ttfp','2026-05-09T20:22:50.748Z','2026-05-09T20:22:50.748Z');

