INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('de67001b-7bad-4086-a869-216081a07343','cab0ef0e-903e-42c6-99fb-592515fb671e','nike-girls-soccer-camp-sacred-heart-university-june-21-24-2026','Nike Girls Soccer Camp Sacred Heart University -  (June 21–24, 2026)','camp','soccer','Join us for the Sacred Heart University Girls Soccer Camp in Fairfield, Connecticut, an immersive summer experience that combines high-level soccer training with a true college-campus atmosphere. Hosted on Sacred Heart’s beautiful campus, this camp offers aspiring players the opportunity to train, live, and grow in an environment designed to mirror the college soccer experience. Led by knowledgeable and dedicated coaches, daily training sessions focus on developing technical skills, tactical understanding, and overall game fundamentals. In addition to on-field training, campers participate in educational presentations covering key performance topics such as sports nutrition, strength training, and athletic development, providing athletes with tools to support success both on and off the field. Campers are housed in campus dormitories, allowing them to experience traditional college living while building friendships, independence, and confidence. The combination of structured soccer training, educational sessions, and a residential setting creates a balanced and enriching environment where players can grow as athletes and individuals. Join us at Sacred Heart University for an intensive, well-rounded week of soccer training and an unforgettable summer camp experience.',8,18,'all','2026-06-21','2026-06-24','$545-$829','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-sacred-heart-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:23:02.055Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:23:03.704Z',200,NULL,NULL,'medium','de67001b-7bad-4086-a869-216081a07343','nike-girls-soccer-camp-sacred-heart-university-june-21-24-2026','2026-05-09T20:23:02.055Z','2026-05-09T20:23:02.055Z');

