INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('02544707-9753-485a-b6d6-03fdaa765ceb','15ee1df9-d13e-4cf8-a2c4-7cf95f4ea366','nike-girls-soccer-camp-at-northen-illinois-university-collegiate-experience-july-j90y','Nike Girls Soccer Camp at Northen Illinois University - Collegiate Experience -  (July 9–11, 2026)','camp','soccer','Take your game to the next level this summer at the Nike Girls Soccer Camp at Northern Illinois University in DeKalb, Illinois. Led by NIU Women’s Soccer Head Coach Michael O’Neill, a Top 10 Nike Soccer Camp Director, this residential camp delivers a true collegiate training experience both on and off the field. Hosted on a Division I campus with state-of-the-art facilities, campers train in an environment that mirrors the intensity, structure, and professionalism of college soccer. Each session is designed to help players elevate their technical and tactical skills while building confidence and understanding of the next level. Beyond training, this camp offers a complete residential experience. Campers live on campus and take part in team-building activities like bowling, karaoke, and group events that foster connection, confidence, and lasting friendships. Designed for players ages 10–18, this camp combines elite-level coaching, competitive training, and a fun, supportive atmosphere. It is an unforgettable opportunity for players to improve their game, experience college life, and be part of a positive and inspiring soccer community. Hear from Head Coach and Camp Director Michael O''Neil: “Our residential camp blends elite training with unforgettable fun, giving players a true college-level experience while helping them grow in confidence, connection, and love for the game.”',10,18,'all','2026-07-09','2026-07-11','$489-$589','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-at-niu-collegiate-experience',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:23:14.803Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:23:16.303Z',200,NULL,NULL,'medium','02544707-9753-485a-b6d6-03fdaa765ceb','nike-girls-soccer-camp-at-northen-illinois-university-collegiate-experience-july-j90y','2026-05-09T20:23:14.803Z','2026-05-09T20:23:14.803Z');

INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('576a3842-ea23-414e-858d-5f2b4638625c','org-67913c2a-dc9e-449d-a073-0deca6026ca1','Nike Soccer Camp at Benedictine University -  (June 19–21, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-benedictine-university','','','5700 College Rd','Lisle','IL','60532',41.7779976,-88.0969936,'Coach Dave DiTomasso has partnered with Spencer Pappas, Head Men’s Soccer Coach at Benedictine University, to offer an exceptional collegiate overnight camp experience at Benedictine University this summer. Now hosted on the Benedictine University campus, this camp provides players with a true college soccer environment—training on quality facilities and experiencing life in a collegiate setting. Please note, this camp was formerly held at Elmhurst University with Coach DiTomasso and has been re','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:23:16.687Z','2026-05-09T20:23:16.687Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('67913c2a-dc9e-449d-a073-0deca6026ca1','576a3842-ea23-414e-858d-5f2b4638625c','nike-soccer-camp-at-benedictine-university-june-19-21-2026-upxy','Nike Soccer Camp at Benedictine University -  (June 19–21, 2026)','camp','soccer','Coach Dave DiTomasso has partnered with Spencer Pappas, Head Men’s Soccer Coach at Benedictine University, to offer an exceptional collegiate overnight camp experience at Benedictine University this summer. Now hosted on the Benedictine University campus, this camp provides players with a true college soccer environment—training on quality facilities and experiencing life in a collegiate setting. Please note, this camp was formerly held at Elmhurst University with Coach DiTomasso and has been regarded as one of the premier soccer camps in the region for decades. Designed for aspiring players, this camp is an outstanding opportunity to strengthen fundamentals and elevate overall performance. Instruction emphasizes functional training, attacking and supporting play, decision-making, finishing, defending, small-sided games, 11v11 play, and creativity. Dedicated goalkeeper training is also provided, ensuring every player receives position-specific development. With a fully immersive overnight experience, campers gain a valuable introduction to college life, staying in residence halls, training daily in a structured collegiate environment, and building connections with players from across the region. This experience is ideal for young athletes looking to understand what it takes to compete and succeed at the next level. Open to players ages 8–18, with overnight eligibility beginning at age 9 (8-year-olds are welcome as extended day campers). Coach DiTomasso’s camp was also recognized as one of North America’s Top 60 Summer Camps of 2017 by FlightNetwork travel agency, highlighting its long-standing reputation for quality instruction and player development.',8,18,'all','2026-06-19','2026-06-21','$539-$629','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-benedictine-university',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:23:16.687Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:23:18.297Z',200,NULL,NULL,'medium','67913c2a-dc9e-449d-a073-0deca6026ca1','nike-soccer-camp-at-benedictine-university-june-19-21-2026-upxy','2026-05-09T20:23:16.687Z','2026-05-09T20:23:16.687Z');

