INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('9b8fbfb3-31f4-4c1f-8384-3c8105060426','836b56b3-2110-4bd6-b2dd-598ce67cba42','mount-soccer-academy-collegiate-experience-camp-july-23-26-2026','Mount Soccer Academy Collegiate Experience Camp -  (July 23–26, 2026)','camp','soccer','Step into the world of Division I soccer at the Mount Soccer Academy Collegiate Experience Camp at Mount St. Mary’s University in Emmitsburg, Maryland. Hosted on the University’s stunning collegiate campus, this highly sought‑after overnight camp has sold out for four consecutive years, offering aspiring players an exclusive opportunity to experience life inside a true Division I training environment. Led by Men’s Head Coach Brett Teach and his accomplished staff, campers train daily on Mount St. Mary’s outstanding athletic facilities in a setting shaped by decades of elite player development. Training sessions reflect the pace and intensity of the college game, blending modern and traditional coaching methods to sharpen technical skills, tactical awareness, and competitive mindset through structured training, small‑sided play, and match competition. The overnight format elevates the experience beyond the field, allowing athletes to live on campus, utilize collegiate facilities, and participate in structured evening activities that promote leadership, accountability, and independence. This residential immersion helps players understand the daily routines, expectations, and culture of a Division I program. Training and competition take place on Mount St. Mary’s well‑maintained collegiate fields, providing campers with a professional‑level environment that supports high‑performance development. Combined with access to campus amenities and a scenic, distraction‑free setting ideal for focused growth, the facilities play a central role in creating an authentic college soccer atmosphere. With elite instruction, Division I insight, exceptional facilities, and a proven track record of demand, the Mount Soccer Academy Collegiate Experience Camp delivers a complete and unforgettable collegiate soccer experience for players ready to take the next step.',10,19,'all','2026-07-23','2026-07-26','$599-$699','day',0,0,'open','https://www.ussportscamps.com/soccer/mount-soccer-academy-collegiate-experience-camp-emmitsburg-md',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:23:19.554Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:23:21.031Z',200,NULL,NULL,'medium','9b8fbfb3-31f4-4c1f-8384-3c8105060426','mount-soccer-academy-collegiate-experience-camp-july-23-26-2026','2026-05-09T20:23:19.554Z','2026-05-09T20:23:19.554Z');

INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('1666de5c-c787-4859-a5b3-816fbf0a0c1f','org-3879fdc2-b21c-4bac-9a93-83b4dd7909ea','Nike Soccer Camp at Endicott College - Overnight Camp (June 25–28, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-endicott-college-girls','','','376 Hale St','Beverly','MA','01915',42.55504,-70.85058,'Experience the Nike Soccer Camp at Endicott College in Beverly, Massachusetts, a premier summer soccer destination set on one of New England’s most scenic college campuses. Overlooking the Atlantic Ocean, Endicott offers outstanding athletic facilities and an ideal setting for an immersive overnight camp that blends high-level soccer training with the full college-residential experience. Designed for players looking to elevate their game in a focused yet supportive environment, the camp is led b','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:23:21.408Z','2026-05-09T20:23:21.408Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('3879fdc2-b21c-4bac-9a93-83b4dd7909ea','1666de5c-c787-4859-a5b3-816fbf0a0c1f','nike-soccer-camp-at-endicott-college-overnight-camp-june-25-28-2026','Nike Soccer Camp at Endicott College - Overnight Camp (June 25–28, 2026)','camp','soccer','Experience the Nike Soccer Camp at Endicott College in Beverly, Massachusetts, a premier summer soccer destination set on one of New England’s most scenic college campuses. Overlooking the Atlantic Ocean, Endicott offers outstanding athletic facilities and an ideal setting for an immersive overnight camp that blends high-level soccer training with the full college-residential experience. Designed for players looking to elevate their game in a focused yet supportive environment, the camp is led by Christine Silva, former Associate Head Coach at Endicott College, alongside a highly qualified coaching staff. Campers train daily using a thoughtful mix of modern and traditional coaching principles, with sessions emphasizing technical proficiency, tactical awareness, and confident execution in competitive game-based scenarios. The highlight of the program is the Girls Overnight Camp, where athletes live on campus, train extensively on Endicott’s top-tier fields, and participate in structured evening activities that enhance team bonding and personal growth. This overnight format allows players to fully immerse themselves in campus life, build lasting friendships, and develop independence, mirroring the rhythm and expectations of collegiate soccer. In addition, the Coed Day Camp provides a high-energy training option for boys and girls seeking elite instruction without the overnight stay, making it a great fit for younger athletes or local players. Across both camp options, athletes will develop their skills, raise their soccer IQ, and enjoy a week filled with competition, learning, and unforgettable moments. Whether you’re aiming to sharpen your fundamentals or experience what it’s like to train in a true college environment, the Nike Soccer Camp at Endicott College delivers a dynamic and memorable summer soccer experience. “As a player, it was always the people and the experience that made camp special. That’s why our camp is built with a passion for the game and a focus on player development, helping athletes grow their skills, confidence, and a lasting love for the game in a positive, supportive environment.” — Christine Silva, Camp Director and Former Women’s Associate Head Coach, Endicott College',8,14,'all','2026-06-25','2026-06-28','$909','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-endicott-college-girls',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:23:21.408Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:23:23.152Z',200,NULL,NULL,'medium','3879fdc2-b21c-4bac-9a93-83b4dd7909ea','nike-soccer-camp-at-endicott-college-overnight-camp-june-25-28-2026','2026-05-09T20:23:21.408Z','2026-05-09T20:23:21.408Z');

