INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('f8f7c6b8-2dfd-482a-bc75-39e6d18e55b6','ef61decb-97d1-46f4-824a-7300c933f5e2','nike-soccer-camp-at-albright-college-june-18-21-2026','Nike Soccer Camp at Albright College -  (June 18–21, 2026)','camp','soccer','Nike Soccer Camps return to Albright College in Reading, Pennsylvania, offering a fun and competitive co‑ed soccer experience for players of all skill levels. Designed to inspire a love for the game, this camp encourages youth athletes to take ownership of their development while training in a supportive and engaging environment. Led by the experienced True Balance Sports Camps (TBSC) coaching staff, campers participate in structured training sessions that blend technical skill development, tactical understanding, and game‑based learning. Using a mix of traditional and modern coaching methods, the curriculum allows every player the opportunity to progress and grow with confidence. Campers have the opportunity to live on campus, creating an immersive overnight camp experience while utilizing Albright University''s facilities. Training, meals, and campus life combine to provide a memorable setting where players build friendships, develop as athletes, and fully enjoy their summer soccer experience. The Nike Soccer Camp at Albright College delivers high‑quality coaching, a positive atmosphere, and an engaging campus environment, helping players improve their game while creating memories that last well beyond camp.',9,16,'all','2026-06-18','2026-06-21','$599-$699','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-albright-college',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:24:17.970Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:24:18.258Z',200,NULL,NULL,'medium','f8f7c6b8-2dfd-482a-bc75-39e6d18e55b6','nike-soccer-camp-at-albright-college-june-18-21-2026','2026-05-09T20:24:17.970Z','2026-05-09T20:24:17.970Z');

