INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('5a4e5109-4680-45f9-ae18-dd8dd668da63','org-a0315366-5370-4713-a77d-c2aae036dc07','Nike Soccer Camp with Prospect Soccer Academy - Memphis -  (June 22–26, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-memphis-tennessee','','','1880 Wolf River Blvd','Memphis','TN','38017',35.1176036,-89.8289538,'Join us for an exciting summer at the Nike Soccer Camp with Prospect Soccer Academy in Collierville, TN, held at St. George’s Independent School. Led by Camp Director Chris Gardea and the Prospect Soccer Academy staff, this camp is open to boys and girls ages 6–14 of all ability levels and provides a high-quality training experience focused on technical development, tactical understanding, and overall soccer IQ in a fun and supportive environment. Prospect Soccer Academy is a premier development','scraped','active',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:33:25.789Z','2026-05-09T20:33:25.789Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('a0315366-5370-4713-a77d-c2aae036dc07','5a4e5109-4680-45f9-ae18-dd8dd668da63','nike-soccer-camp-with-prospect-soccer-academy-memphis-june-22-26-2026-4nwy','Nike Soccer Camp with Prospect Soccer Academy - Memphis -  (June 22–26, 2026)','camp','baseball','Join us for an exciting summer at the Nike Soccer Camp with Prospect Soccer Academy in Collierville, TN, held at St. George’s Independent School. Led by Camp Director Chris Gardea and the Prospect Soccer Academy staff, this camp is open to boys and girls ages 6–14 of all ability levels and provides a high-quality training experience focused on technical development, tactical understanding, and overall soccer IQ in a fun and supportive environment. Prospect Soccer Academy is a premier development program led by former professional players who run a full-time academy dedicated to developing players at every stage of their soccer journey. With extensive playing and coaching experience, the staff delivers a high-energy, player-focused environment centered on confidence, growth, and long-term development. Set just outside Memphis in Collierville, TN, St. George’s Independent School offers outstanding soccer facilities, including well-maintained grass fields and a professional training environment ideal for player development. The campus provides a focused, safe, and high-quality setting for a full week of soccer training. The curriculum blends proven fundamentals with modern, game-based training designed to improve decision-making, technical ability, and performance under pressure. This camp is a great opportunity for young players in the Memphis area to learn, compete, and grow under experienced, passionate coaches while building confidence and a love for the game. Hear from Co-Owner of Prospect Soccer Academy and Camp Director Harry Forrester: "Our camps are delivered by seasoned professional players and coaches who bring real game experience into every session. Built around a proven, development-first philosophy, we prioritize technical excellence through high-repetition training and game-realistic scenarios such as 1v1 and 2v2, helping players build confidence, decision-making, and creativity under pressure. Just as important is the environment we create, structured, supportive, and professionally led, where players are encouraged to take risks, learn from mistakes, and grow. Our goal is for every player to leave not only as a more complete footballer, but with greater confidence, resilience, and a genuine love for the game.”',6,14,'all','2026-06-22','2026-06-26','$275-$385','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-memphis-tennessee',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','parentcoachplaybook@gmail.com','2026-05-09T20:33:25.789Z',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,'live','2026-05-09T20:33:27.381Z',200,NULL,NULL,'medium','a0315366-5370-4713-a77d-c2aae036dc07','nike-soccer-camp-with-prospect-soccer-academy-memphis-june-22-26-2026-4nwy','2026-05-09T20:33:25.789Z','2026-05-09T20:33:25.789Z');

