INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('f5f22c2f-3882-4368-8528-34441230efef','a5e8dd9d-7830-42bf-95f9-fc72567bb0a0','nike-girls-soccer-camp-in-eagle-june-22-26-2026','Nike Girls Soccer Camp in Eagle -  (June 22–26, 2026)','camp','soccer','Each day blends high-level tactical and technical training with competitive gameplay, while intentionally teaching athletes confidence, grit, and resilience. The camp curriculum, designed by Indie Chicas President Allison Gibson, is rooted in self-belief and growth mindset, encouraging campers to train hard, take risks, embrace mistakes, and discover what they’re capable of. Through a fun yet challenging environment, players learn that mistakes are not setbacks, but powerful tools for growth and self-trust. Led by an experienced collegiate coaching staff, this camp fosters a supportive, female-centered space where athletes build skills, leadership, and lasting friendships. Campers leave not only sharper technically, but more confident, motivated, and inspired to bring their learning back to their teams and into all areas of their lives.',4,16,'all','2026-06-22','2026-06-26','$155-$355','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-eagle',NULL,NULL,'','','scraped','active',50,'ussportscamps.com',NULL,'approved','pare