INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('0f317bda-958c-469e-88c5-2ddc8c39027c','org-cfdcb62b-b635-4083-9bcd-0237fb462cf6','Nike Soccer Camp with Soccer IQ Academy in Colorado Springs -  (July 13–17, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-soccer-iq-academy-colorado-springs','','','7040 Rangewood Dr','Colorado Springs','CO','80923',38.9209001,-104.7365856,'The Nike Soccer Camp with Soccer IQ Academy in Colorado Springs delivers a high‑energy, transformational training experience powered by the state’s top youth development program. Soccer IQ Academy, known for producing numerous collegiate and professional players, brings its world‑class methodology to Cottonwood Creek Park, giving athletes the perfect opportunity to sharpen their skills, elevate their soccer IQ, and head into the fall season with confidence. This “Complete Player” camp blends tec','scraped','unverified',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:38:41.408Z','2026-05-09T20:38:41.408Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('cfdcb62b-b635-4083-9bcd-0237fb462cf6','0f317bda-958c-469e-88c5-2ddc8c39027c','nike-soccer-camp-with-soccer-iq-academy-in-colorado-springs-july-13-17-2026','Nike Soccer Camp with Soccer IQ Academy in Colorado Springs -  (July 13–17, 2026)','camp','soccer','The Nike Soccer Camp with Soccer IQ Academy in Colorado Springs delivers a high‑energy, transformational training experience powered by the state’s top youth development program. Soccer IQ Academy, known for producing numerous collegiate and professional players, brings its world‑class methodology to Cottonwood Creek Park, giving athletes the perfect opportunity to sharpen their skills, elevate their soccer IQ, and head into the fall season with confidence. This “Complete Player” camp blends technical training with position‑specific work to build smart, versatile athletes. Players sharpen defending, midfield play, and attacking skills while mastering finishing in realistic game situations. Daily training boosts footwork, passing, ball control, speed, and agility, all guided by SIQ’s modern, IQ‑driven curriculum. Through small‑sided games and high‑pressure scenarios, athletes elevate their decision‑making, vision, creativity, and confidence in every phase of play. The camp is led by Soccer IQ Academy’s elite coaching staff, using a Barcelona‑influenced curriculum developed by a USSF A‑licensed coach. Each SIQ coach brings collegiate or professional experience, holds official coaching certifications, and completes SafeSport training, background checks, and specialized SIQ methodology training, ensuring players receive instruction held to the highest standard. Hear from Camp Director Yura Kulikov: "At Soccer IQ Academy, we don’t just train players to be better on the ball, we teach them how to think the game. Every session is built around real game situations so players develop decision-making, awareness, and confidence, all while having fun and building a true love for soccer Our camps consistently receive strong feedback from both players and parents because of the balance we create between development and enjoyment. Many players return year after year, and we pride ourselves on creating an environment where kids are excited to come back every day.We also keep coach-to-player interaction high, ensuring every player is seen, coached, and supported throughout the camp." Train Smarter, Play Faster and Become the Complete Player with SIQ Academy and Nike Soccer Camps!',5,15,'all','2026-07-13','2026-07-17','$359','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-soccer-iq-academy-colorado-springs',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T20:38:41.408Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T20:38:43.136Z',200,NULL,NULL,'medium','cfdcb62b-b635-4083-9bcd-0237fb462cf6','nike-soccer-camp-with-soccer-iq-academy-in-colorado-springs-july-13-17-2026','2026-05-09T20:38:41.408Z','2026-05-09T20:38:41.408Z');

INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('9f9a67c1-3862-4081-bf90-31b44f37503a','org-bbdada35-2c94-4cc2-91df-e4aa03005d58','Nike Soccer Camp with Soccer IQ Academy - High School Players - Westlands Park -  (June 30–July 2, 2026)','other','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-soccer-iq-academy-high-school-players-westlands-park-co','','','5701 S Quebec St','Greenwood Village','CO','80111',39.612993,-104.904203,'This Nike Soccer Camp with Soccer IQ Academy brings SIQ Academy’s proven development model to Westlands Park in Greenwood Village. Designed for high school aged players 14-18, this evening camp delivers high‑intensity, modern training for serious athletes preparing for the upcoming club and high school seasons. The camp features three evening training sessions, each with clear objectives and competitive intensity. Players focus on improving technical quality, soccer specific conditioning, 1v1 at','scraped','unverified',0,NULL,NULL,NULL,NULL,50,'2026-05-09T20:38:44.184Z','2026-05-09T20:38:44.184Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('bbdada35-2c94-4cc2-91df-e4aa03005d58','9f9a67c1-3862-4081-bf90-31b44f37503a','nike-soccer-camp-with-soccer-iq-academy-high-school-players-westlands-park-june-','Nike Soccer Camp with Soccer IQ Academy - High School Players - Westlands Park -  (June 30–July 2, 2026)','camp','soccer','This Nike Soccer Camp with Soccer IQ Academy brings SIQ Academy’s proven development model to Westlands Park in Greenwood Village. Designed for high school aged players 14-18, this evening camp delivers high‑intensity, modern training for serious athletes preparing for the upcoming club and high school seasons. The camp features three evening training sessions, each with clear objectives and competitive intensity. Players focus on improving technical quality, soccer specific conditioning, 1v1 attacking and defending, and finishing, helping them sharpen their game and enter preseason confident and match‑ready. All sessions are led by Soccer IQ Academy’s elite coaching staff, using a Barcelona‑influenced curriculum created by a USSF A‑licensed coach. All SIQ Academy coaches bring collegiate or professional experience, are fully licensed and SafeSport‑certified, and follow internal SIQ training standards, ensuring the highest level of instruction at every Nike Soccer Camp. Whether preparing for club tryouts, high school tryouts, or preseason, the Nike Soccer Camp with Soccer IQ Academy – High School Players – Westlands Park is an ideal way to train smarter, improve confidence, and be ready to compete. Hear from Camp Director Yura Kulikov: "At Soccer IQ Academy, we don’t just train players to be better on the ball, we teach them how to think the game. Every session is built around real game situations so players develop decision-making, awareness, and confidence, all while having fun and building a true love for soccer Our camps consistently receive strong feedback from both players and parents because of the balance we create between development and enjoyment. Many players return year after year, and we pride ourselves on creating an environment where kids are excited to come back every day.We also keep coach-to-player interaction high, ensuring every player is seen, coached, and supported throughout the camp."',14,18,'all','2026-06-30','2026-07-02','$189','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-soccer-iq-academy-high-school-players-westlands-park-co',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T20:38:44.184Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T20:38:45.981Z',200,NULL,NULL,'medium','bbdada35-2c94-4cc2-91df-e4aa03005d58','nike-soccer-camp-with-soccer-iq-academy-high-school-players-westlands-park-june-','2026-05-09T20:38:44.184Z','2026-05-09T20:38:44.184Z');

