INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('528caf6d-83a3-4bcd-95f1-0106da8a959a','5604f14e-4732-41df-bb6c-8d945aa014cc','nike-soccer-camp-in-arcadia-los-angeles-june-29-july-3-2026-8e5o','Nike Soccer Camp in Arcadia - Los Angeles -  (June 29–July 3, 2026)','camp','soccer','Experience high‑level training and nonstop fun this summer at the Nike Soccer Camp at Arcadia High School. Designed to help players grow both technically and tactically, this camp offers an exciting, confidence‑building environment where athletes can sharpen their skills and elevate their overall game. The camp is directed by Chris Ferrer, respected youth development expert, Arcadia High School Boys Head Coach, and leader within Los Angeles Soccer Camps, one of Southern California’s most trusted youth soccer organizations. Supported by LA Soccer Camps’ proven player‑development model, campers will train in a structured yet fun setting that emphasizes technical excellence, game understanding, and competitive play. Open to boys and girls ages 6–14 of all ability levels, the program features a low coach‑to‑camper ratio, ensuring every player receives personalized instruction, plenty of touches on the ball, and meaningful feedback. Through dynamic drills, small‑sided games, and match play, campers will develop new skills, refine technique, boost confidence, and leave camp better prepared for the next stage of their soccer journey.',6,14,'all','2026-06-29','2026-07-03','$330','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-arcadia-los-angeles',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T20:40:13.977Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T20:40:14.317Z',200,NULL,NULL,'medium','528caf6d-83a3-4bcd-95f1-0106da8a959a','nike-soccer-camp-in-arcadia-los-angeles-june-29-july-3-2026-8e5o','2026-05-09T20:40:13.977Z','2026-05-09T20:40:13.977Z');

