INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('ef0034ae-fa3c-4cc8-917c-885a904a772c','b669720a-39c8-4229-9724-6d2c699585f5','nike-soccer-camp-with-beyond-the-baller-santa-barbara-aug-3-7-2026','Nike Soccer Camp with Beyond the Baller - Santa Barbara -  (Aug. 3–7, 2026)','camp','soccer','Join us this summer at the Nike Soccer Camp with Beyond the Baller in Santa Barbara, CA, led by Camp Director Hannah Adler, a former professional player in both the U.S. and Europe, and a two‑time U.S. Beach Soccer Player of the Year. Set in the picturesque coastal city of Santa Barbara, this camp blends world‑class coaching with one of the most beautiful training environments in the country. Whether you''re a beginner or an experienced player, our program is designed to help every athlete grow. The dynamic curriculum provides personalized instruction focused on developing technical skills, tactical awareness, and overall game understanding. Under Hannah’s leadership, campers benefit from a coaching philosophy rooted in creativity, confidence, and player‑centered development. In addition to a full week of high‑level training, this camp offers a unique experience you won’t find anywhere else. Friday’s entire camp day will take place at iconic West Beach, where athletes will close out the week playing beach soccer, an exciting, fast‑paced variation of the game led by Hannah, one of the nation’s premier beach soccer talents. Elevate your game, enjoy the sun and sand, and experience a one‑of‑a‑kind soccer adventure on the California coast!',6,14,'all','2026-08-03','2026-08-07','$310-$430','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-beyond-the-baller-santa-barbara',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T20:43:06.617Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T20:43:06.903Z',200,NULL,NULL,'medium','ef0034ae-fa3c-4cc8-917c-885a904a772c','nike-soccer-camp-with-beyond-the-baller-santa-barbara-aug-3-7-2026','2026-05-09T20:43:06.617Z','2026-05-09T20:43:06.617Z');

