.',7,14,'all','2026-08-02','2026-08-06','$759-$1010','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-peddie-school',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T20:49:28.613Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T20:49:30.363Z',200,NULL,NULL,'medium','aaa3b343-e5a8-4457-9a7a-87fc958a5e82','nike-soccer-camp-at-the-peddie-school-juniors-camp-aug-2-6-2026','2026-05-09T20:49:28.613Z','2026-05-09T20:49:28.613Z');

