INSERT OR IGNORE INTO organizations (id,slug,name,organization_type,website_url,email,phone,address,city,state,zip,latitude,longitude,description,record_source,record_status,is_claimed,claimed_by_email,claim_paid_until,logo_key,gallery_keys,confidence_score,created_at,updated_at) VALUES ('4a7c3946-19a3-4618-9904-8dde8e61bc8c','org-98faadcc-5ec7-44bf-825e-3a6e46fdaf8e','Robert Morris University Girls Soccer Camp -  (June 8–12, 2026)','other','https://www.ussportscamps.com/soccer/nike/girls-soccer-camp-robert-morris-university','','','Robert Morris Soccer Stadium','Moon Township','PA','15108',NULL,NULL,'The Robert Morris University Girls Soccer Camp offers a high-quality day camp soccer experience for girls ages 6–14 at Robert Morris Soccer Stadium in Moon Township, Pennsylvania. Conveniently located just outside Pittsburgh, this camp serves families throughout Allegheny County and the greater Western PA region. Led by Head Women''s Soccer Coach Michelle Rick, the camp provides expert instruction rooted in collegiate training principles while remaining fun, supportive, and age-appropriate. Open ','scraped','unverified',0,NULL,NULL,NULL,NULL,50,'2026-05-09T21:16:51.057Z','2026-05-09T21:16:51.057Z');
INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('98faadcc-5ec7-44bf-825e-3a6e46fdaf8e','4a7c3946-19a3-4618-9904-8dde8e61bc8c','robert-morris-university-girls-soccer-camp-june-8-12-2026-9vtr','Robert Morris University Girls Soccer Camp -  (June 8–12, 2026)','camp','soccer','The Robert Morris University Girls Soccer Camp offers a high-quality day camp soccer experience for girls ages 6–14 at Robert Morris Soccer Stadium in Moon Township, Pennsylvania. Conveniently located just outside Pittsburgh, this camp serves families throughout Allegheny County and the greater Western PA region. Led by Head Women''s Soccer Coach Michelle Rick, the camp provides expert instruction rooted in collegiate training principles while remaining fun, supportive, and age-appropriate. Open to players of all skill levels, campers will work on developing their technical abilities, game understanding, and confidence through structured training sessions and small-sided play. Camp sessions focus on foundational skills such as ball control, passing, dribbling, and finishing, paired with competitive games that encourage creativity, teamwork, and decision-making. Training takes place at Robert Morris Soccer Stadium, giving campers the opportunity to learn and compete in an authentic collegiate soccer environment. Hear from Head Women''s Soccer Coach &amp; Camp Director Michelle Rick: "Our goal is simple... create a fun, positive environment where kids can learn the game, play, and enjoy being on the field with their friends. This camp is perfect for young players of all levels who want to stay active, have fun, and improve their soccer skills over the summer. Whether new to the game or already playing, campers will enjoy a supportive environment focused on learning, playing, and enjoying the game with others."',5,13,'all','2026-06-08','2026-06-12','$255-$355','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/girls-soccer-camp-robert-morris-university',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T21:16:51.057Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T21:16:52.674Z',200,NULL,NULL,'medium','98faadcc-5ec7-44bf-825e-3a6e46fdaf8e','robert-morris-university-girls-soccer-camp-june-8-12-2026-9vtr','2026-05-09T21:16:51.057Z','2026-05-09T21:16:51.057Z');

