INSERT OR IGNORE INTO programs (id,organization_id,slug,name,program_type,activity_category,description,age_min,age_max,skill_level,session_start_date,session_end_date,price_text,day_or_overnight,lunch_included,aftercare_available,availability_status,registration_url,registration_deadline,schedule_text,contact_email,contact_phone,record_source,record_status,confidence_score,source_domain,hero_photo_key,pcd_status,submitted_by_email,submitted_at,reviewed_by,reviewed_at,review_notes,reject_reason_code,verified,awaiting_review,featured,featured_order,featured_until,url_health_status,url_last_checked_at,url_last_status_code,last_edited_at,last_edited_by,pcd_confidence,legacy_camp_id,legacy_slug,created_at,updated_at) VALUES ('c82c5deb-0e19-4fd8-ad20-014485432f5b','bd730e63-9acf-4e6c-8004-61a2dae21baa','nike-soccer-camp-at-the-university-of-hartford-july-6-10-2026','Nike Soccer Camp at the University of Hartford -  (July 6–10, 2026)','camp','soccer','Get ready for an unforgettable week of soccer development at the Nike Soccer Camp at the University of Hartford in West Hartford, Connecticut, where boys and girls ages 5–16 train on a beautiful, state‑of‑the‑art collegiate campus. This camp is designed for players of all skill levels, from beginners to experienced competitors, making it the perfect summer training experience for every young athlete. (Please note: ages 5–6 participate in half‑day sessions only.) Led by University of Hartford Men’s Soccer Head Coach Mike Kulas and his talented collegiate staff, this high‑energy camp blends modern coaching methods with proven player‑development techniques. Coach Kulas and his team create an environment where every athlete is challenged, supported, and inspired to elevate their game, whether they’re learning the basics, sharpening their technique, or striving to compete at the next level. Campers will enjoy a dynamic training curriculum featuring technical skill‑building, attacking and defending concepts, small‑sided games, ball mastery work, and competitive match play, all delivered with the enthusiasm and structure Nike Soccer Camps are known for. Surrounded by premier facilities and a fun, encouraging atmosphere, players build confidence, improve soccer IQ, and experience meaningful growth throughout the week. Join us this summer at the University of Hartford and take your game to new heights with elite coaching, incredible facilities, and an unforgettable soccer experience!',5,16,'all','2026-07-06','2026-07-10','$319-$439','day',0,0,'open','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-university-hartford',NULL,NULL,'','','scraped','unverified',50,'ussportscamps.com',NULL,'pending','parentcoachplaybook@gmail.com','2026-05-09T21:17:00.037Z',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,'live','2026-05-09T21:17:01.553Z',200,NULL,NULL,'medium','c82c5deb-0e19-4fd8-ad20-014485432f5b','nike-soccer-camp-at-the-university-of-hartford-july-6-10-2026','2026-05-09T21:17:00.037Z','2026-05-09T21:17:00.037Z');

